dialogues=[]
for job in jobs:
    numbers={key:i+1 for i,(key,_) in enumerate(job['refs'])}
    text=f"尺寸：16:9\n模型：seedance2.5\n声音：有声音\n时长：{job['duration']}秒\n\n## 参考图\n\n{job['purpose']}\n\n编号：{job['id']}。本条参考图必须按下方顺序实际上传，路径文字不能代替附件；不上传其他旧稿图片。不使用音频参考，音色以文字描述约束。\n\n"
    for key,role in job['refs']:
        p=REF/sources[key][0]; n=numbers[key]
        text+=f"### 图片{n}｜{p.stem}\n\n本地路径：`{p.as_posix()}`\n\n用途：{role}\n\n![图片{n}](<{p.as_posix()}>)\n\n"
    text+='## 视频生成 Prompt\n\n'
    text+='参考对应：'+'；'.join(f"图片{numbers[key]}用于{role}" for key,role in job['refs'])+' 所有参考图按职责使用，不按上传顺序轮播，不把身份照当影片镜头。\n\n'
    text+='整体画面：'+GENERAL+job['overall']+'\n\n### 固定声音身份（控制说明，不朗读）\n\n'
    for v in job['voices']: text+='- '+v+'\n'
    text+='\n声音编号只是制作约束，不是模型锁声参数；不保证天然声纹一致，实际成片仍需听验。所有人仅朗读各镜“唯一允许发声的原句”引号内的文字；角色名、受话人、画内画外、编号、动作和本稿说明绝不发声。台词自然稍快但完整，不吞字，不把正常动作整体加速。\n\n'
    for i,s in enumerate(job['shots'],1):
        text+=f"### 分镜{i}｜{s['start']}-{s['end']}秒\n\n"
        text+=f"参考图关系：{s['refs']}\n\n画面与动作：{s['action']}\n\n摄影与切点：{s['camera']}\n\n声音执行（仅为控制说明，不朗读）：{s['voice']}\n\n"
        allowed=' '.join('“'+line+'”' for line in s['lines']) if s['lines'] else NO
        text+='唯一允许发声的原句：'+allowed+'\n\n'
        for line in s['lines']: dialogues.append(dict(request=job['id'],shot=i,start=s['start'],end=s['end'],text=line,voice=s['voice']))
    text+='### 全片约束\n\n连续性与限制：'+job['continuity']+'\n\n'+clean+'\n\n'+job['method']+'\n\n声音要求：'+job['sound']+'仅朗读各镜“唯一允许发声的原句”引号内真实台词，绝不朗读角色名、声音编号、标题或导演说明；所有无原句镜头禁止额外人声。\n'
    (OUT/job['filename']).write_text(text,encoding='utf-8')

