(OUT/'audit/production-record.json').write_text(json.dumps(record,ensure_ascii=False,indent=2),encoding='utf-8')
(OUT/'audit/dialogue-map.json').write_text(json.dumps(dialogues,ensure_ascii=False,indent=2),encoding='utf-8')

checks=[]
for job in jobs:
    p=OUT/job['filename']; t=p.read_text(encoding='utf-8')
    assert t.startswith(f"尺寸：16:9\n模型：seedance2.5\n声音：有声音\n时长：{job['duration']}秒\n"),p
    assert '{{' not in t and '}}' not in t,p
    intervals=[(float(a),float(b)) for a,b in re.findall(r'### 分镜\d+｜([\d.]+)-([\d.]+)秒',t)]
    assert intervals[0][0]==0 and intervals[-1][1]==job['duration'],p
    assert all(a[1]==b[0] for a,b in zip(intervals,intervals[1:])),p
    assert t.count('唯一允许发声的原句：')==len(intervals),p
    assert t.count('参考图关系：')==len(intervals),p
    for path in re.findall(r'本地路径：`([^`]+)`',t): assert Path(path).is_file(),path
    assert t.rfind('声音要求：')>t.rfind('拍摄手法参考：')>t.rfind('连续性与限制：'),p
    assert '\n##' not in t[t.rfind('声音要求：'):],p
    refs_in_shots=[int(n) for s in job['shots'] for n in re.findall(r'图片(\d+)',s['refs'])]
    assert all(1<=n<=len(job['refs']) for n in refs_in_shots),p
    checks.append(dict(file=p.name,shots=len(intervals),duration=job['duration'],attachments=len(job['refs']),all_paths_exist=True,full_timeline=True,last_paragraph_sound=True))
report=dict(ok=True,checks=checks,dialogue_count=len(dialogues),note='仅文档结构、时段、路径和逐句来源检查；非成片听审或用户通过。')
(OUT/'audit/document-validation.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8')
print(json.dumps(report,ensure_ascii=False,indent=2))
